package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
final class CoverEditorDialog {
 static void show(Context c,JSONObject profile,Runnable saved){String source=profile.optString("banner_url","");if(source.isEmpty()||source.equals("null")){Toast.makeText(c,"Adicione uma capa primeiro",Toast.LENGTH_SHORT).show();return;}NativeSheet sheet=new NativeSheet(c,"Posicionar capa");ProfileCoverView preview=new ProfileCoverView(c,source);preview.setBackground(AppStyle.shape(preview,0xff201a2b,16));sheet.body.addView(preview,new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,180)));AccountImageLoader.load(preview,source);int[] values={50,50,100};try{String f=android.net.Uri.parse(source).getFragment();String raw=android.net.Uri.parse("https://cover.invalid/?"+f).getQueryParameter("bc-cover");if(raw!=null){String[] a=raw.split(",");for(int i=0;i<Math.min(3,a.length);i++)values[i]=(int)Float.parseFloat(a[i]);}}catch(Exception ignored){}String[] labels={"Posição horizontal","Posição vertical","Zoom"};for(int i=0;i<3;i++){int index=i,min=i==2?25:0,max=i==2?250:100;values[i]=Math.min(max,Math.max(min,values[i]));TextView label=NativeSheet.text(c,labels[i]+" • "+values[i]+"%",13,0xffcab5e6);sheet.body.addView(label);SeekBar slider=new SeekBar(c);slider.setMax(max-min);slider.setProgress(values[i]-min);sheet.body.addView(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int n,boolean user){values[index]=n+min;label.setText(labels[index]+" • "+values[index]+"%");preview.position(values[0],values[1],values[2]);}});}preview.position(values[0],values[1],values[2]);TextView state=NativeSheet.text(c,"",13,0xffb7a6ff);sheet.body.addView(state);Button save=new Button(c);save.setText("Salvar posição");AppStyle.button(save,true);sheet.body.addView(save);save.setOnClickListener(v->{save.setEnabled(false);sheet.busy(true);new AccountRepository(c).coverPosition(values[0],values[1],values[2],(r,e)->{sheet.busy(false);if(e!=null){state.setText(e);return;}sheet.dialog.dismiss();saved.run();});});sheet.show();}
}
